/** Path prefix identifying a rules-directory file (the "diff touches .minsky/rules/**" trigger half). */
export const RULES_DIR_PREFIX = ".minsky/rules/";

/**
 * Growth threshold (BYTES — see the module-header unit note) above which a
 * rules-touching PR must carry a `Size-budget justification:` marker.
 * Calibrated per the mt#2874 spec's §Thresholds grounding: ~the smallest
 * deliberate rule addition observed (mt#2801 added ~3.3K; incidental
 * same-day growths ran 2.7-3K) — a one-line factual edit stays comfortably
 * under it. Reductions (delta <= 0) never trigger regardless of magnitude.
 * Exposed as a named export (not inlined) so the value is tunable from one
 * place and directly assertable in tests.
 */
export const GROWTH_THRESHOLD_BYTES = 2000;

/** The file whose growth this gate prices. */
export const TARGET_FILE = "CLAUDE.md";

// ---------------------------------------------------------------------------
// Per-rule ceiling, priced at the authoring PR (mt#3676)
// ---------------------------------------------------------------------------
//
// The 15K per-rule ceiling (mt#1876/mt#2874) was enforced ONLY at pre-commit,
// so a breach failed whichever agent committed next regardless of what they
// touched — three sessions paid an override in one morning for a
// `hook-observers` breach none of them authored. mt#3676 splits that in two:
// pre-commit now blocks only a commit that STAGES an offending rule, and this
// gate bills the PR that pushed the rule over.
//
// Same trigger as the aggregate check above (the PR touches `.minsky/rules/**`),
// same operator override, and the same `Size-budget justification:` marker.
// Parity is deliberate: mt#3676 moves WHERE the cost is charged, not WHAT the
// ceiling allows, and a merge gate stricter than the commit gate would be
// surprising in the other direction.

/** A rule over the ceiling, as the compile command reports it. */
export interface PerRuleViolation {
  id: string;
  size: number;
}

/**
 * Map `.minsky/rules/<id>.mdc` to `<id>`; null for anything else.
 *
 * The id segment is `[^/]+`, NOT `.+` (PR #2652 R1). The rules directory is
 * read by a NON-RECURSIVE `readdir` filtered on `.endsWith(".mdc")`
 * (`packages/domain/src/rules/operations/file-operations.ts`), so a nested
 * `.minsky/rules/sub/foo.mdc` is never loaded as a rule and can never appear in
 * `perRuleViolations`. A greedy capture would mint an id (`sub/foo`) that
 * matches no violation, so the PR would silently escape being billed for a real
 * breach — the exact mis-attribution this gate exists to prevent, inverted.
 */
export function ruleIdFromRulesPath(filename: string): string | null {
  const m = /^\.minsky\/rules\/([^/]+)\.mdc$/.exec(filename);
  return m?.[1] ?? null;
}

/**
 * The offending rules THIS PR touched — the ones it should be billed for.
 *
 * A PR is not blocked for a rule that was already over the ceiling and which it
 * never edited; that breach belongs to whoever authored it, which is the whole
 * point of mt#3676. Intersecting rather than blocking on any violation is what
 * keeps this gate from re-creating the mispricing at merge time.
 */
export function findTouchedCeilingBreaches(
  violations: readonly PerRuleViolation[],
  prFiles: readonly PrFile[]
): PerRuleViolation[] {
  const touched = new Set(
    prFiles
      .map((f) => ruleIdFromRulesPath(f.filename ?? ""))
      .filter((id): id is string => typeof id === "string")
  );
  return violations.filter((v) => touched.has(v.id));
}

/**
 * Read the per-rule ceiling violations for the working tree at `cwd` by asking
 * the compiler, which is the only thing that knows a rule's COMPILED
 * contribution — that differs from its source body (measured: `hook-observers`
 * 6060 chars at source, 5983 compiled), and a source-side approximation would
 * decide the verdict wrongly for any rule near the line.
 *
 * Returns `null` when the answer could not be obtained (command missing, spawn
 * failure, unparseable output). `null` means "unknown" and the caller WARNS
 * rather than denying — a merge gate that hard-fails on its own tooling being
 * unavailable would block every rules PR the moment the CLI moves.
 */
export function readPerRuleViolations(cwd: string): PerRuleViolation[] | null {
  let stdout: string;
  try {
    const proc = Bun.spawnSync(
      ["bun", "run", "src/cli.ts", "compile", "--check", "--target", "claude.md"],
      { cwd, stdout: "pipe", stderr: "pipe", timeout: 60_000 }
    );
    stdout = proc.stdout.toString();
  } catch {
    return null;
  }
  const start = stdout.indexOf("{");
  const end = stdout.lastIndexOf("}");
  if (start === -1 || end === -1 || end <= start) return null;
  let parsed: unknown;
  try {
    parsed = JSON.parse(stdout.slice(start, end + 1));
  } catch {
    return null;
  }
  if (parsed === null || typeof parsed !== "object") return null;
  const raw = (parsed as { perRuleViolations?: unknown }).perRuleViolations;
  if (!Array.isArray(raw)) return null;
  const violations: PerRuleViolation[] = [];
  for (const entry of raw) {
    if (entry === null || typeof entry !== "object") continue;
    const { id, size } = entry as { id?: unknown; size?: unknown };
    if (typeof id === "string" && id.length > 0 && typeof size === "number") {
      violations.push({ id, size });
    }
  }
  return violations;
}

/** Deny text for a PR that pushed one or more rules past the per-rule ceiling. */
export function buildPerRuleCeilingDenyMessage(breaches: readonly PerRuleViolation[]): string {
  const list = breaches.map((b) => `  - ${b.id} (${b.size} chars)`).join("\n");
  return (
    `Merge blocked: this PR grows ${breaches.length === 1 ? "a rule" : "rules"} past the ` +
    `per-rule ceiling for always-loaded context:\n${list}\n\n` +
    `The ceiling is charged to the PR that crosses it, so it is not paid by whoever commits ` +
    `next (mt#3676). Resolve by one of:\n` +
    `  1. Trim or SPLIT the rule — the ladder's intended remedy (mt#1876/mt#2987).\n` +
    `  2. Move content down the admission ladder instead of \`alwaysApply: true\`.\n` +
    `  3. Add a \`Size-budget justification:\` section to the PR body naming why this rule must ` +
    `stay always-loaded at this size (use mcp__minsky__session_pr_edit).\n` +
    `  4. Operator override: set \`${OVERRIDE_ENV_VAR}=1\` (audit-logged).`
  );
}

// ---------------------------------------------------------------------------
// File-path matching
// ---------------------------------------------------------------------------

/** True when `filename` lives under `.minsky/rules/`. Null/undefined-safe. */
export function isRulesDirFile(filename: string | null | undefined): boolean {
  if (typeof filename !== "string") return false;
  return filename.startsWith(RULES_DIR_PREFIX);
}

/**
 * Filter a PR's changed files to those touching `.minsky/rules/**`. Mirrors
 * `findDeploySurfaceFiles`'s two-check shape (deploy-surface-detector.ts):
 * checks BOTH `filename` (covers added/modified/removed) and
 * `previous_filename` (covers a rename INTO or OUT OF the rules dir) so a
 * rename away from `.minsky/rules/` still counts as a rules-dir change.
 */
export function findRulesDirFiles(files: PrFile[]): string[] {
  return files
    .filter((f) => isRulesDirFile(f.filename) || isRulesDirFile(f.previous_filename))
    .map((f) => f.filename);
}

// ---------------------------------------------------------------------------
// PR body marker parsing (mt#2648 accepted forms)
// ---------------------------------------------------------------------------

/**
 * Marker for the size-budget justification (mt#2648 — same accepted-forms
 * class as `hasExecutionEvidence` / `hasDeployVerification`). Accepts,
 * case-insensitive:
 *   A. A Markdown heading (any level 1-6) + "size-budget justification"
 *      with an OPTIONAL trailing colon.
 *   B. A plain label line — "size-budget justification:" with a REQUIRED
 *      colon (no heading marker) — keeps the colon required here so bare
 *      prose mentions don't false-positive.
 * Up to 3 leading spaces before a heading marker, per CommonMark.
 */
const SIZE_BUDGET_JUSTIFICATION_MARKER =
  /^(?: {0,3}(#{1,6})\s+size-budget justification\s*:?|size-budget justification\s*:)\s*(.*)$/im;

/**
 * True when the PR body contains a `Size-budget justification:` block with
 * non-empty content following the marker. Mirrors `hasExecutionEvidence`'s
 * discipline: HTML comments stripped first; a "No Size-budget
 * justification:" negation does NOT qualify; content must follow the
 * marker (inline or on subsequent lines before the next heading).
 */
export function hasSizeBudgetJustification(prBody: string): boolean {
  const stripped = prBody.replace(/<!--[\s\S]*?-->/g, "");
  const lines = stripped.split("\n");
  const fenceInternal = computeFenceInternalLines(lines);
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line === undefined) continue;
    const match = line.match(SIZE_BUDGET_JUSTIFICATION_MARKER);
    if (!match) continue;

    // Negation guard: "No Size-budget justification:" / "## No Size-budget justification:".
    const beforeMarker = line.slice(0, line.toLowerCase().indexOf("size-budget")).toLowerCase();
    if (/\bno\b/.test(beforeMarker)) continue;

    const parts: string[] = [];
    const inlineContent = (match[2] ?? "").trim();
    if (inlineContent.length > 0) parts.push(inlineContent);
    for (let j = i + 1; j < lines.length; j++) {
      const nextLine = lines[j];
      if (nextLine === undefined) break;
      // Only a REAL heading ends the section (PR #2533 R1). Third instance of the
      // same class: this gate's MARKER scan already rejects a fence-quoted marker
      // (verified — `hasSizeBudgetJustification(fence-quoted only) -> false`), so
      // mt#3530's spec scoped it out on that question; the CONTENT scan is a
      // separate sub-issue the R1 review surfaced, and it is present here too.
      if (!fenceInternal[j] && /^ {0,3}#{1,6}\s/.test(nextLine)) break;
      if (nextLine.trim().length > 0) parts.push(nextLine.trim());
    }
    if (parts.join(" ").trim().length === 0) continue; // empty section — keep looking

    return true;
  }
  return false;
}

// ---------------------------------------------------------------------------
// Core check logic (pure / injectable)
// ---------------------------------------------------------------------------

export interface GrowthJustificationCheckResult {
  /** Whether merge should be blocked. */
  blocked: boolean;
  /** Human-readable reason if blocked; undefined if allowed. */
  reason?: string;
  /** Rules-directory files found in the PR diff (empty when the gate is silent). */
  rulesFiles: string[];
  /**
   * `headSizeBytes - baseSizeBytes` for the target file. `null` only when
   * the gate never reached the size comparison (no rules files touched).
   */
  deltaBytes: number | null;
  /** Whether the justification marker was found (only meaningful when growth exceeded the threshold). */
  justificationFound: boolean;
  /** Any non-fatal warnings to surface. */
  warnings: string[];
}

/**
 * Evaluate the growth-justification check given the PR's changed files, its
 * body, and the target file's measured size (BYTES — see module-header unit
 * note) at head and at the PR's merge-base. Pure core of the hook —
 * injectable for unit tests (no `gh` calls happen in here; the top-level
 * entrypoint below resolves the two sizes and passes them in).
 *
 * `thresholdBytes` defaults to {@link GROWTH_THRESHOLD_BYTES} (the production
 * value) but is overridable — this is the seam live-verification uses to
 * exercise the deny path against a REAL PR's real (but sub-2000) growth with
 * a deliberately lowered test threshold, per §7a's "low test threshold via
 * fixture/env" dual-mode discipline (mt#2874 PR body has the worked example).
 */
export function checkGrowthJustification(
  files: PrFile[],
  prBody: string,
  headSizeBytes: number,
  baseSizeBytes: number,
  thresholdBytes: number = GROWTH_THRESHOLD_BYTES
): GrowthJustificationCheckResult {
  const warnings: string[] = [];
  const rulesFiles = findRulesDirFiles(files);

  // Diff doesn't touch .minsky/rules/** → hook is silent, regardless of size delta.
  if (rulesFiles.length === 0) {
    return {
      blocked: false,
      rulesFiles: [],
      deltaBytes: null,
      justificationFound: false,
      warnings,
    };
  }

  const deltaBytes = headSizeBytes - baseSizeBytes;

  // Reductions (delta <= 0) and sub-threshold growth never trigger — a plain
  // "<=" comparison, not "<", so a delta exactly AT the threshold does not
  // yet trigger (parity with the acceptance test's "growth 1.5K -> allowed"
  // case and the general "exceeds" framing in the spec: the gate fires once
  // growth is STRICTLY greater than the threshold).
  if (deltaBytes <= thresholdBytes) {
    return {
      blocked: false,
      rulesFiles,
      deltaBytes,
      justificationFound: false,
      warnings,
    };
  }

  if (hasSizeBudgetJustification(prBody)) {
    return {
      blocked: false,
      rulesFiles,
      deltaBytes,
      justificationFound: true,
      warnings,
    };
  }

  const reason = buildDenyMessage(deltaBytes, rulesFiles, thresholdBytes);
  return {
    blocked: true,
    reason,
    rulesFiles,
    deltaBytes,
    justificationFound: false,
    warnings,
  };
}

/**
 * Build the deny message. Per the mt#2874 spec: states the measured delta,
 * reproduces the rule-admission ladder (kept byte-consistent with the
 * key-architecture.mdc bullet and the create-rule skill — see mt#2874 PR
 * body for the cross-check), and names the marker form.
 */
function buildDenyMessage(
  deltaBytes: number,
  rulesFiles: string[],
  thresholdBytes: number = GROWTH_THRESHOLD_BYTES
): string {
  const fileList = rulesFiles.map((f) => `  - ${f}`).join("\n");
  return (
    `Merge blocked: this PR touches .minsky/rules/** and grows ${TARGET_FILE} by ` +
    `${deltaBytes} bytes (threshold: ${thresholdBytes} bytes) with no ` +
    `\`Size-budget justification:\` marker in the PR body.\n\n` +
    `Rule-admission ladder — new guidance content defaults DOWN:\n` +
    `  1. path-scoped \`.claude/rules\` — file-shaped guidance\n` +
    `  2. skill — task-shaped guidance\n` +
    `  3. memory — incident-shaped guidance\n` +
    `  4. docs — reference-shaped guidance\n` +
    `  5. \`alwaysApply: true\` — LAST, reserved for genuinely per-turn discipline ` +
    `(mt#1876 criterion: "would removal cause an agent to skip a check it runs every turn?")\n\n` +
    `Rules files touched:\n${fileList}\n\n` +
    `To unblock, choose one of:\n` +
    `  1. Add a \`Size-budget justification:\` section (plain label with colon, or a Markdown ` +
    `heading of any level with an optional trailing colon) to the PR body naming why this ` +
    `content must be always-loaded and which cheaper channels above were rejected ` +
    `(use mcp__minsky__session_pr_edit to update the body).\n` +
    `  2. Move the content down the ladder instead of \`alwaysApply: true\`.\n` +
    `  3. Operator override: set \`${OVERRIDE_ENV_VAR}=1\` (audit-logged).`
  );
}

// ---------------------------------------------------------------------------
// Top-level hook entry point
// ---------------------------------------------------------------------------

if (import.meta.main) {
  const startMs = Date.now();
  const input = await readInput<ToolHookInput>();
  // mt#3084 (evaluation-loop Phase 3): fire-log every evaluation, exactly
  // once per invocation regardless of which exit fires below.
  const fireLogContext: MergeGateFireLogContext = {};
  const recordAndExit: RecordAndExit = makeRecordAndExit(
    GUARD_NAME,
    startMs,
    input,
    undefined,
    fireLogContext
  );

  // Operator override: skip with an audit line on stdout. This is the
  // ESTABLISHED convention across this hook family, verified by direct
  // inspection (not assumed) — `grep -rn "override active" .minsky/hooks/*.ts`
  // shows 14+ hooks writing their override-audit line to `process.stdout`,
  // including the DIRECTLY comparable sibling
  // `require-deploy-verification-before-merge.ts` (same event, same
  // `session_pr_merge` matcher, same "operator override on a merge gate"
  // shape), which writes via `process.stdout.write` and says so explicitly
  // ("matching the sibling override-audit convention"). The one exception in
  // the family is `block-subagent-bypass-merge.ts` (`console.error`/stderr),
  // which is a DIFFERENT shape — a hard, no-fail-open, main-agent-only
  // bypass audit trail, not a "gate skipped, audit and move on" line. stdout
  // is correct here; Claude Code's hook-output parser tolerates a non-JSON
  // stdout line by logging "Ignoring non-JSON line" and proceeding (verified
  // empirically by every sibling hook using this exact pattern in
  // production). This line does NOT echo the env value — MINSKY_SKIP_SIZE_
  // JUSTIFICATION is a boolean flag, not a secret, but omitting the value
  // keeps the audit line stable regardless of which truthy spelling
  // ("1"/"true"/"yes") was used. (mt#3084 R1: several sibling merge-gate
  // hooks — `require-deploy-verification-before-merge.ts`,
  // `require-checks-on-bypass-merge.ts`, `require-review-before-merge.ts` —
  // previously DID echo the raw value; reviewer BLOCKING #2 flagged this as
  // a secret-handling-posture violation and all were brought in line with
  // this file's presence-only convention. This was the correct pattern all
  // along, not merely "unlike most siblings.")
  if (isOverrideSet()) {
    process.stdout.write(
      `[growth-justification] override active: ${OVERRIDE_ENV_VAR} set at ` +
        `${new Date().toISOString()} — growth-justification gate skipped (value not echoed)\n`
    );
    recordAndExit("allow", {
      overrideEnvVar: OVERRIDE_ENV_VAR,
      overrideClassification: classifyOverride(OVERRIDE_ENV_VAR),
    });
  }

  // mt#3355: `session_pr_merge` takes EITHER `task` or `sessionId`, both optional. Reading
  // `tool_input.task` alone and exiting `allow` when empty meant a `sessionId`-invoked
  // merge silently skipped this gate entirely. Resolve through the shared resolver, record
  // which source produced the id, and WARN rather than allow when neither does.
  const resolution = resolveMergeGateTaskId(input);
  fireLogContext.taskResolutionSource = resolution.source;
  const task = resolution.taskId;
  if (!task) {
    writeOutput({
      hookSpecificOutput: {
        hookEventName: "PreToolUse",
        additionalContext: `⚠️ ${unresolvedTaskWarning(GUARD_NAME)}`,
      },
    });
    // mt#3920: UNSET, deliberately — no task id resolved, so the gate never ran its
    // check. Neither a clean decision nor a crash: nothing broke, there was simply
    // nothing to check against.
    recordAndExit("warn");
  }

  const repo = deriveRepoFromGit(input.cwd);
  if (!repo) {
    writeOutput({
      hookSpecificOutput: {
        hookEventName: "PreToolUse",
        additionalContext:
          "⚠️ [growth-justification] Could not derive owner/repo from git remote — check skipped.",
      },
    });
    // mt#3920: `crashed` — repo derivation failed, so the gate could not run. The warn is
    // a fail-open on a broken probe, not a verdict (same call as the sibling gates).
    recordAndExit("warn", undefined, "crashed");
  }

  const context = fetchPrContext(repo, { task, cwd: input.cwd, include: { files: true } });

  if (!context.ok) {
    writeOutput({
      hookSpecificOutput: {
        hookEventName: "PreToolUse",
        additionalContext: formatContextFailureWarnings(context)
          .map((w) => `⚠️ ${w}`)
          .join("\n"),
      },
    });
    // mt#3920: `crashed` — the PR-context fetch failed, so the check never ran. Fail-open
    // on a broken probe, not a verdict.
    recordAndExit("warn", undefined, "crashed");
  }

  const { headSha, baseBranch, body: prBody, files: prFiles, warnings: topLevelWarnings } = context;

  // Cheap short-circuit BEFORE the size-comparison `gh` calls: a PR that
  // doesn't touch .minsky/rules/** never needs the merge-base/head size
  // fetch — saves 2 `gh` round-trips on the common case (most PRs don't
  // touch rules at all).
  const rulesFiles = findRulesDirFiles(prFiles);
  if (rulesFiles.length === 0) {
    // mt#3920: `decided` — the file list was fetched and scanned; a PR that touches no
    // rules is a verdict on real data, not a short-circuit taken before the check.
    if (topLevelWarnings.length > 0) {
      writeOutput({
        hookSpecificOutput: {
          hookEventName: "PreToolUse",
          additionalContext: topLevelWarnings.map((w) => `⚠️ ${w}`).join("\n"),
        },
      });
      recordAndExit("warn", undefined, "decided");
    }
    recordAndExit("allow", undefined, "decided");
  }

  // mt#3676: per-rule ceiling, checked BEFORE the aggregate size comparison —
  // it needs no `gh` round-trips, and a PR that crossed the ceiling should be
  // told about the specific rule rather than about total CLAUDE.md growth.
  // Skipped entirely when the PR body already carries the justification marker,
  // which covers both checks (see the section header above for why parity).
  if (!hasSizeBudgetJustification(prBody)) {
    const violations = readPerRuleViolations(input.cwd);
    if (violations === null) {
      writeOutput({
        hookSpecificOutput: {
          hookEventName: "PreToolUse",
          additionalContext:
            `⚠️ [growth-justification] Could not read per-rule ceiling state from the compiler ` +
            `— per-rule check skipped (the aggregate check below still ran).`,
        },
      });
    } else {
      const breaches = findTouchedCeilingBreaches(violations, prFiles);
      if (breaches.length > 0) {
        writeOutput({
          hookSpecificOutput: {
            hookEventName: "PreToolUse",
            permissionDecision: "deny",
            permissionDecisionReason: buildPerRuleCeilingDenyMessage(breaches),
          },
        });
        // mt#3920: `decided` — the per-rule ceiling state was read and evaluated.
        recordAndExit("deny", undefined, "decided");
      }
    }
  }

  const mergeBaseSha = fetchMergeBaseSha(repo, baseBranch, headSha, { cwd: input.cwd });
  if (!mergeBaseSha) {
    writeOutput({
      hookSpecificOutput: {
        hookEventName: "PreToolUse",
        additionalContext:
          `⚠️ [growth-justification] Could not resolve merge-base commit for ${baseBranch}...` +
          `${headSha} — size-justification check skipped.`,
      },
    });
    // mt#3920: `crashed` — the merge-base fetch failed, so the size comparison never ran.
    recordAndExit("warn", undefined, "crashed");
  }

  const headSizeBytes = fetchFileSizeAtRef(repo, TARGET_FILE, headSha, { cwd: input.cwd });
  const baseSizeBytes = fetchFileSizeAtRef(repo, TARGET_FILE, mergeBaseSha, { cwd: input.cwd });

  if (headSizeBytes === null || baseSizeBytes === null) {
    writeOutput({
      hookSpecificOutput: {
        hookEventName: "PreToolUse",
        additionalContext:
          `⚠️ [growth-justification] Could not fetch ${TARGET_FILE} size at head or merge-base ` +
          `— size-justification check skipped.`,
      },
    });
    // mt#3920: `crashed` — the size fetch failed, so the comparison never ran.
    recordAndExit("warn", undefined, "crashed");
  }

  const result = checkGrowthJustification(prFiles, prBody, headSizeBytes, baseSizeBytes);
  const allWarnings = [...topLevelWarnings, ...result.warnings];

  if (result.blocked) {
    const warningContext =
      allWarnings.length > 0 ? `${allWarnings.map((w) => `⚠️ ${w}`).join("\n")}\n\n` : "";
    writeOutput({
      hookSpecificOutput: {
        hookEventName: "PreToolUse",
        permissionDecision: "deny",
        permissionDecisionReason: `${warningContext}${result.reason}`,
      },
    });
    // mt#3920: the three exits below are all downstream of `checkGrowthJustification` —
    // the gate exercised its check and reached a verdict.
    recordAndExit("deny", undefined, "decided");
  } else if (allWarnings.length > 0) {
    writeOutput({
      hookSpecificOutput: {
        hookEventName: "PreToolUse",
        additionalContext: allWarnings.map((w) => `⚠️ ${w}`).join("\n"),
      },
    });
    recordAndExit("warn", undefined, "decided");
  }
  recordAndExit("allow", undefined, "decided");
}
